INSERT INTO `wp_postmeta` (`meta_id`, `post_id`, `meta_key`, `meta_value`) VALUES
(2147, 15986, '_elementor_data', '[{\"id\":\"38d7117d\",\"elType\":\"container\",\"settings\":{\"flex_direction\":\"column\",\"flex_gap\":{\"column\":\"20\",\"row\":\"20\",\"isLinked\":true,\"unit\":\"px\",\"size\":20},\"content_width\":\"full\",\"width\":{\"unit\":\"%\",\"size\":132.305},\"_flex_size\":\"none\",\"_element_width\":\"initial\",\"padding\":{\"unit\":\"px\",\"top\":\"0\",\"right\":\"0\",\"bottom\":\"0\",\"left\":\"0\",\"isLinked\":true},\"custom_css\":\"selector table {\\n    margin-bottom: 0;\\n}\"},\"elements\":[{\"id\":\"7c7d3114\",\"elType\":\"widget\",\"settings\":{\"editor\":\"<p>This course is a detailed and easy tutorial to get you all setup and going with the use of LearnPress LMS Plugin. It is a free and simple plugin to help you create an Online Courses Website step by step. The tutorial guides you through the configuration of the plugin, creation of Courses, Lessons, Quizzes, and finally guides you on how to boost up your Website with Premium LearnPress Add-ons brought to you by ThimPress (creator of LearnPress). It also shows how you could configure additional items like the course layouts and featured images ...<\\/p>\",\"content_width\":\"full\",\"__globals__\":{\"text_color\":\"\"}},\"elements\":[],\"widgetType\":\"text-editor\"},{\"id\":\"7d85d6f6\",\"elType\":\"widget\",\"settings\":{\"editor\":\"<p>Master Adobe Photoshop CC 2024 without any previous knowledge. Learn the newest AI tricks to get fast results like a pro<\\/p>\",\"content_width\":\"full\",\"__globals__\":{\"text_color\":\"\"}},\"elements\":[],\"widgetType\":\"text-editor\"},{\"id\":\"ba529ce\",\"elType\":\"widget\",\"settings\":{\"title\":\"What you\'ll learn\",\"size\":\"h4\",\"line\":\"\",\"__globals__\":{\"_background_color\":\"globals\\/colors?id=ec35f56\",\"textcolor\":\"\"},\"_background_color\":\"#F4F4F4\",\"heading_margin\":{\"unit\":\"px\",\"top\":\"0\",\"right\":\"0\",\"bottom\":\"0\",\"left\":\"0\",\"isLinked\":false},\"content_width\":\"full\"},\"elements\":[],\"widgetType\":\"thim-heading\"},{\"id\":\"2772f611\",\"elType\":\"widget\",\"settings\":{\"group\":[{\"text\":\"Automate tasks on their computer by writing simple Python programs.\",\"_id\":\"bc0e691\",\"icons\":{\"value\":{\"id\":15989,\"url\":\"http:\\/\\/luatsu.local\\/wp-content\\/uploads\\/2024\\/10\\/check.svg\"},\"library\":\"svg\"}},{\"text\":\" Programmatically generate and update Excel spreadsheets.\",\"icons\":{\"value\":{\"id\":15989,\"url\":\"http:\\/\\/luatsu.local\\/wp-content\\/uploads\\/2024\\/10\\/check.svg\"},\"library\":\"svg\"},\"_id\":\"21fb6b3\"},{\"text\":\"Crawl web sites and pull information from online sources.\",\"icons\":{\"value\":{\"id\":15989,\"url\":\"http:\\/\\/luatsu.local\\/wp-content\\/uploads\\/2024\\/10\\/check.svg\"},\"library\":\"svg\"},\"_id\":\"6aab9a9\"},{\"text\":\" Use Python\'s debugging tools to quickly figure out bugs in your code.\",\"icons\":{\"value\":{\"id\":15989,\"url\":\"http:\\/\\/luatsu.local\\/wp-content\\/uploads\\/2024\\/10\\/check.svg\"},\"library\":\"svg\"},\"_id\":\"1871bbf\"},{\"text\":\"Write programs that can do text pattern recognition with \\\"regular expressions\\\"\",\"icons\":{\"value\":{\"id\":15989,\"url\":\"http:\\/\\/luatsu.local\\/wp-content\\/uploads\\/2024\\/10\\/check.svg\"},\"library\":\"svg\"},\"_id\":\"ca92da5\"},{\"text\":\"Parse PDFs and Word documents.\",\"icons\":{\"value\":{\"id\":15989,\"url\":\"http:\\/\\/luatsu.local\\/wp-content\\/uploads\\/2024\\/10\\/check.svg\"},\"library\":\"svg\"},\"_id\":\"9f51cfd\"},{\"text\":\"Write programs that send out email notifications.\",\"icons\":{\"value\":{\"id\":15989,\"url\":\"http:\\/\\/luatsu.local\\/wp-content\\/uploads\\/2024\\/10\\/check.svg\"},\"library\":\"svg\"},\"_id\":\"34b21cc\"},{\"text\":\"Programmatically control the mouse and keyboard to click and type for you.\",\"icons\":{\"value\":{\"id\":15989,\"url\":\"http:\\/\\/luatsu.local\\/wp-content\\/uploads\\/2024\\/10\\/check.svg\"},\"library\":\"svg\"},\"_id\":\"18b7436\"}]